TEST("a new matrix is zero-filled") {
  Matrix m(2, 3);
  CHECK_EQ(m.rows(), std::size_t{2});
  CHECK_EQ(m.cols(), std::size_t{3});
  for (std::size_t r = 0; r < 2; ++r)
    for (std::size_t c = 0; c < 3; ++c) CHECK_EQ(m(r, c), 0.0);
}

TEST("build from rows; ragged rows throw") {
  Matrix m{{1, 2, 3}, {4, 5, 6}};
  CHECK_EQ(m.rows(), std::size_t{2});
  CHECK_EQ(m(1, 2), 6.0);
  CHECK_THROWS((Matrix{{1, 2}, {3}}), std::invalid_argument);
}

TEST("at() is bounds-checked") {
  Matrix m(2, 2);
  m.at(1, 1) = 5;
  CHECK_EQ(m(1, 1), 5.0);
  CHECK_THROWS(m.at(2, 0), std::out_of_range);
  CHECK_THROWS(m.at(0, 2), std::out_of_range);
  const Matrix& cm = m;
  CHECK_THROWS(cm.at(5, 5), std::out_of_range);
}

TEST("addition, with a shape check") {
  Matrix a{{1, 2}, {3, 4}}, b{{10, 20}, {30, 40}};
  CHECK(a + b == (Matrix{{11, 22}, {33, 44}}));
  CHECK_THROWS(a + Matrix(2, 3), std::invalid_argument);
}

TEST("matrix product, with a shape check") {
  Matrix a{{1, 2, 3}, {4, 5, 6}};          // 2x3
  Matrix b{{7, 8}, {9, 10}, {11, 12}};     // 3x2
  CHECK(a * b == (Matrix{{58, 64}, {139, 154}}));
  CHECK_THROWS(a * a, std::invalid_argument);
}

TEST("identity and transpose") {
  Matrix a{{1, 2, 3}, {4, 5, 6}};
  CHECK(Matrix::identity(2) * a == a);
  CHECK(a * Matrix::identity(3) == a);
  CHECK(a.transpose() == (Matrix{{1, 4}, {2, 5}, {3, 6}}));
}

TEST("copies are independent") {
  Matrix a{{1, 2}, {3, 4}};
  Matrix b = a;
  b(0, 0) = 99;
  CHECK_EQ(a(0, 0), 1.0);
  CHECK(!(a == b));
}

